package anonaadhaar

import (
	"encoding/json"
	"math/big"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestQRData(t *testing.T) {
	// expected source
	// https://github.com/anon-aadhaar/anon-aadhaar/blob/main/packages/circuits/assets/test.json
	source := `{
  "testQRData": "",
  "undefined": "V2",
  "Email_mobile_present_bit_indicator_value": "3",
  "ReferenceId": "269720240420014552930",
  "Name": "Sumit Kumar",
  "DOB": "01-01-1984",
  "Gender": "M",
  "CareOf": "C/O Ishwar Chand",
  "District": "East Delhi",
  "Landmark": "",
  "House": "B-31, 3rd Floor",
  "Location": "",
  "PinCode": "110051",
  "PostOffice": "Krishna Nagar",
  "State": "Delhi",
  "Street": "Radhey Shyam Park Extension",
  "SubDistrict": "Gandhi Nagar",
  "VTC": "Krishna Nagar",
  "PhoneNumberLast4": "1234"
}`

	expected := map[string]string{}
	err := json.Unmarshal([]byte(source), &expected)
	require.NoError(t, err)

	qrDataBI, ok := big.NewInt(0).SetString(expected["testQRData"], 10)
	require.True(t, ok)
	actual := &AnonAadhaarDataV2{}
	err = actual.UnmarshalQR(qrDataBI)
	require.NoError(t, err)

	assert.Equal(t, expected["undefined"], actual.Version, "Version mismatch")
	assert.Equal(
		t,
		expected["Email_mobile_present_bit_indicator_value"],
		actual.ContactIndecator,
		"ContactIndicator mismatch",
	)
	assert.Equal(t, expected["ReferenceId"], actual.ReferenceID, "ReferenceID mismatch")
	assert.Equal(t, expected["Name"], actual.Name, "Name mismatch")
	assert.Equal(
		t,
		expected["DOB"],
		actual.DateOfBirth.Format(mm_dd_yyyy_template),
		"DateOfBirth mismatch",
	)
	assert.Equal(t, expected["Gender"], actual.Gender, "Gender mismatch")
	assert.Equal(t, expected["CareOf"], actual.Address.CareOf, "CareOf mismatch")
	assert.Equal(t, expected["District"], actual.Address.District, "District mismatch")
	assert.Equal(t, expected["Landmark"], actual.Address.Landmark, "Landmark mismatch")
	assert.Equal(t, expected["House"], actual.Address.House, "House mismatch")
	assert.Equal(t, expected["Location"], actual.Address.Location, "Location mismatch")
	assert.Equal(t, expected["PinCode"], actual.Address.PinCode, "PinCode mismatch")
	assert.Equal(t, expected["PostOffice"], actual.Address.PostOffice, "PostOffice mismatch")
	assert.Equal(t, expected["State"], actual.Address.State, "State mismatch")
	assert.Equal(t, expected["Street"], actual.Address.Street, "Street mismatch")
	assert.Equal(t, expected["SubDistrict"], actual.Address.SubDistrict, "SubDistrict mismatch")
	assert.Equal(t, expected["VTC"], actual.Address.VTC, "VTC mismatch")
	assert.Equal(
		t,
		expected["PhoneNumberLast4"],
		actual.MobileLastDigits,
		"MobileLastDigits mismatch",
	)
	assert.Equal(
		t,
		expected["PhoneNumberLast4"],
		actual.MobileLastDigits,
		"MobileLastDigits mismatch",
	)
	assert.Equal(
		t,
		"C/O Ishwar Chand;East Delhi;;B-31, 3rd Floor;;110051;Krishna Nagar;Delhi;Radhey Shyam Park Extension;Gandhi Nagar;Krishna Nagar",
		actual.Address.String(),
		"Address mismatch",
	)
}

func TestQRCode_Error(t *testing.T) {
	tests := []struct {
		name             string
		input            string // QR data as string
		expectedErr      error
		errorDescription string
	}{
		{
			name:             "InvalidCompressedData",
			input:            "12345",
			expectedErr:      ErrInvalidQRData,
			errorDescription: "failed to create zlib/gzip reader",
		},
		{
			name:             "InvaldQRData",
			input:            "850400046232713924999233579253012674317057313623715898524149001289727",
			expectedErr:      ErrInvalidQRData,
			errorDescription: "failed to read compressed data",
		},
		{
			name:             "DataTooShort",
			input:            "15687112013125644301735075435176996302272495538819733116582858381282914932227915091279872",
			expectedErr:      ErrInvalidQRData,
			errorDescription: "uncompressed data too short",
		},
		{
			name:             "InvalidPartsCount",
			input:            "",
			expectedErr:      ErrInvalidQRData,
			errorDescription: "invalid number of data fields",
		},
		{
			name:             "InvalidDOBFormat",
			input:            "",
			expectedErr:      ErrInvalidQRVersion,
			errorDescription: "failed to parse date of birth",
		},
		{
			name:             "InvalidSignedTimeFormat",
			input:            "",
			expectedErr:      ErrInvalidQRVersion,
			errorDescription: "failed to parse signed time",
		},
		{
			name:             "InvalidGenderValue",
			input:            "",
			expectedErr:      ErrInvalidQRVersion,
			errorDescription: "failed to verify Aadhaar QR: invalid gender: 'P'",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			qrDataBI, ok := big.NewInt(0).SetString(tt.input, 10)
			require.True(t, ok, "Failed to convert input to big.Int")

			actual := &AnonAadhaarDataV2{}
			err := actual.UnmarshalQR(qrDataBI)
			require.ErrorIs(t, err, tt.expectedErr)
			require.ErrorContains(t, err, tt.errorDescription)
		})
	}
}
